  SELECT x FROM UNNEST(ARRAY[42291396,29947987,48060711,14633473,54380806,44825065,25671490,9440203,17127616,54534889,51147636,49098839,41784217,38537077,39416249,36884562,49280621,47138351,51796994,30746643,17261546,44801796,36831395,10260779,50778969,45110064,10880652,50150500,29363567,50333028,52991215,40398545,46476346,50867376,8433965,52094959,50199385,35403330,53030169,12344842,22512363,26876034,42274233,45667190,9731866,8984946,35392530,52763886,13852464,32294782,22900013,51790978,21308447,29888438,44801195,22227610,23931552,50332842,45662457,50792530,53916502,32215568,17810121,52607259,16617150,36614775,52094952,15581817,49781006,53686226,26642505,37702481,53754347,43307191,46890099,51102257,54003468,28908802,47326455,20368321]) AS t(x)
  UNION ALL
  SELECT x FROM UNNEST(ARRAY[28848550,37343043,47586484,50698350,40686194,44800349,24126935,41715907]) AS t(x)
)
, ev AS (
  SELECT ux.mri_session_id, ux.event_name, TRY_CAST(ux.route_id_train_no AS BIGINT) AS route_id
  FROM user_interaction.ui_ux_events ux
  WHERE ux.__time >= CAST('2026-08-05 18:30:00' AS TIMESTAMP)
    AND ux.__time < CAST('2026-08-18 18:30:00' AS TIMESTAMP)
    AND (ux.selected_country = 'India' OR ux.header_country = 'IND')
    AND ux.event_name IN ('SeatImgSectionClicked', 'NewImagesClicked', 'NewBusImageLoaded')
)
SELECT
  COUNT(DISTINCT CASE WHEN ev.event_name IN ('SeatImgSectionClicked', 'NewImagesClicked') THEN ev.mri_session_id END) AS numerator_sessions,
  COUNT(DISTINCT CASE WHEN ev.event_name = 'NewBusImageLoaded' THEN ev.mri_session_id END) AS denominator_sessions,
  COUNT(DISTINCT CASE WHEN ev.event_name IN ('SeatImgSectionClicked', 'NewImagesClicked') THEN ev.mri_session_id END) * 100.0
    / NULLIF(COUNT(DISTINCT CASE WHEN ev.event_name = 'NewBusImageLoaded' THEN ev.mri_session_id END), 0) AS ctr_pct
FROM ev
INNER JOIN route_list rl ON ev.route_id = rl.x
